CREATE OR REPLACE FUNCTION public.ensure_daily_availability_reset()
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_today date := public.current_business_date();
  v_last_business_date date;
begin
  perform pg_advisory_xact_lock(707200072);

  insert into public.availability_day_state(singleton_key, business_date, reset_at)
  values (true, v_today, now())
  on conflict (singleton_key) do nothing;

  select business_date
  into v_last_business_date
  from public.availability_day_state
  where singleton_key = true
  for update;

  if v_last_business_date < v_today then
    update public.profiles
    set availability = 'unavailable'
    where role::text = 'agent'
      and is_active;

    update public.rotation_state
    set current_profile_id = null,
        version = version + 1,
        updated_at = now(),
        updated_by = null
    where kind::text in ('whatsapp', 'ringcentral', 'workload');

    update public.user_notifications
    set read_at = now()
    where notification_type = 'turn'
      and read_at is null;

    update public.availability_day_state
    set business_date = v_today,
        reset_at = now()
    where singleton_key = true;

    return true;
  end if;

  return false;
end;
$function$

CREATE OR REPLACE FUNCTION public.pass_my_turn(p_rotation rotation_kind, p_reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me public.profiles%rowtype;
  v_state public.rotation_state%rowtype;
  v_next uuid;
begin
  if not public.is_agent() then raise exception 'Agent permission required'; end if;
  if p_rotation = 'workload' then
    raise exception 'Additional Workload turns cannot be passed. Take the task and use Customer Service overflow after acceptance when needed.';
  end if;
  if nullif(trim(p_reason), '') is null then raise exception 'A pass reason is required'; end if;

  perform public.ensure_daily_availability_reset();

  select * into v_me from public.profiles where id = auth.uid() and is_active for update;
  if not found then raise exception 'Active profile not found'; end if;

  select * into v_state from public.rotation_state where kind = p_rotation for update;
  if v_state.current_profile_id is distinct from v_me.id then raise exception 'This turn belongs to another agent'; end if;

  v_next := public.next_eligible_profile(
    p_rotation,
    case when p_rotation = 'whatsapp' then v_me.whatsapp_position else v_me.ringcentral_position end
  );
  if v_next is null then raise exception 'No eligible next agent'; end if;

  update public.rotation_state
  set current_profile_id = v_next,
      version = version + 1,
      updated_at = now(),
      updated_by = v_me.id
  where kind = p_rotation;

  insert into public.turn_events(rotation, action, actor_profile_id, previous_profile_id, next_profile_id, reason)
  values (p_rotation, 'pass', v_me.id, v_me.id, v_next, btrim(p_reason));

  return v_next;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_my_availability(p_status availability_status)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me public.profiles%rowtype;
  v_rotation public.rotation_state%rowtype;
  v_next uuid;
  v_previous uuid;
  v_eligible boolean;
  v_current_usable boolean;
  v_started_today boolean;
begin
  if not public.is_agent() then raise exception 'Agent permission required'; end if;

  perform public.ensure_daily_availability_reset();

  select * into v_me
  from public.profiles
  where id = auth.uid() and is_active
  for update;

  if not found then raise exception 'Active profile not found'; end if;

  update public.profiles
  set availability = p_status
  where id = v_me.id;

  if p_status = 'available' then
    for v_rotation in select * from public.rotation_state order by kind for update loop
      v_eligible := case
        when v_rotation.kind = 'whatsapp' then v_me.whatsapp_active
        when v_rotation.kind = 'ringcentral' then v_me.ringcentral_active
        else v_me.workload_active
      end;

      if v_eligible then
        if v_rotation.current_profile_id is null then
          select exists (
            select 1
            from public.daily_rotation_starts d
            where d.business_date = public.current_business_date()
              and d.rotation = v_rotation.kind
          ) into v_started_today;

          if not v_started_today then
            insert into public.daily_rotation_starts(business_date, rotation, starter_profile_id)
            values (public.current_business_date(), v_rotation.kind, v_me.id)
            on conflict (business_date, rotation) do nothing;
          end if;

          update public.rotation_state
          set current_profile_id = v_me.id,
              version = version + 1,
              updated_at = now(),
              updated_by = v_me.id
          where kind = v_rotation.kind;

          insert into public.turn_events(rotation, action, actor_profile_id, previous_profile_id, next_profile_id, reason)
          values (
            v_rotation.kind,
            case when v_started_today then 'auto_skip' else 'daily_start' end,
            v_me.id,
            null,
            v_me.id,
            case when v_started_today then 'Empty queue resumed when an eligible agent became available' else 'First eligible agent available for the business day' end
          );
        else
          select exists (
            select 1 from public.profiles p
            where p.id = v_rotation.current_profile_id
              and p.is_active
              and p.role = 'agent'
              and p.availability = 'available'
              and case
                when v_rotation.kind = 'whatsapp' then p.whatsapp_active
                when v_rotation.kind = 'ringcentral' then p.ringcentral_active
                else p.workload_active
              end
          ) into v_current_usable;

          if not v_current_usable then
            v_previous := v_rotation.current_profile_id;

            update public.rotation_state
            set current_profile_id = v_me.id,
                version = version + 1,
                updated_at = now(),
                updated_by = v_me.id
            where kind = v_rotation.kind;

            insert into public.turn_events(rotation, action, actor_profile_id, previous_profile_id, next_profile_id, reason)
            values (v_rotation.kind, 'auto_skip', v_me.id, v_previous, v_me.id, 'Stale queue corrected when an eligible agent became available');
          end if;
        end if;
      end if;
    end loop;
  else
    for v_rotation in select * from public.rotation_state order by kind for update loop
      if v_rotation.current_profile_id = v_me.id then
        v_next := public.next_eligible_profile(
          v_rotation.kind,
          case
            when v_rotation.kind = 'whatsapp' then v_me.whatsapp_position
            when v_rotation.kind = 'ringcentral' then v_me.ringcentral_position
            else v_me.workload_position
          end
        );

        update public.rotation_state
        set current_profile_id = v_next,
            version = version + 1,
            updated_at = now(),
            updated_by = v_me.id
        where kind = v_rotation.kind;

        insert into public.turn_events(rotation, action, actor_profile_id, previous_profile_id, next_profile_id, reason)
        values (
          v_rotation.kind,
          'auto_skip',
          v_me.id,
          v_me.id,
          v_next,
          case when v_next is null then 'Agent became unavailable and no eligible agent is currently available' else 'Agent became unavailable' end
        );
      end if;
    end loop;
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.claim_linked_workload_turn(p_related_quote_source_work_item_id uuid, p_work_type work_type, p_change_type text DEFAULT NULL::text, p_note text DEFAULT NULL::text)
 RETURNS work_items
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me public.profiles%rowtype;
  v_state public.rotation_state%rowtype;
  v_next uuid;
  v_item public.work_items%rowtype;
  v_customer_name text;
  v_dealer_id uuid;
  v_quote_owner_id uuid;
  v_quote_assigned_id uuid;
begin
  if not public.is_agent() then raise exception 'Agent permission required'; end if;
  if p_work_type not in ('activation', 'change') then raise exception 'Additional Workload only accepts activations or changes'; end if;
  if p_related_quote_source_work_item_id is null then raise exception 'Select the existing quote this workload belongs to'; end if;

  perform public.ensure_daily_availability_reset();

  select * into v_me from public.profiles where id = auth.uid() and is_active for update;
  if not found then raise exception 'Active profile not found'; end if;
  if v_me.availability <> 'available' or not v_me.workload_active then raise exception 'Set your status to Available before taking Additional Workload'; end if;

  select q.customer_name, q.dealer_id, q.original_owner_profile_id, q.assigned_profile_id
  into v_customer_name, v_dealer_id, v_quote_owner_id, v_quote_assigned_id
  from (
    select w.customer_name, w.dealer_id, w.original_owner_profile_id, w.assigned_profile_id, w.created_at as stage_at
    from public.work_items w
    where w.id = p_related_quote_source_work_item_id
      and w.work_type in ('new_quote', 'requote')
    union all
    select p.customer_name, p.dealer_id, p.original_owner_profile_id, p.assigned_profile_id, p.price_sent_at
    from public.pending_pricing_quotes p
    where p.source_work_item_id = p_related_quote_source_work_item_id
    union all
    select o.customer_name, o.dealer_id, o.original_owner_profile_id, o.assigned_profile_id, o.finalized_at
    from public.quote_outcomes o
    where o.source_work_item_id = p_related_quote_source_work_item_id
  ) q
  order by q.stage_at desc
  limit 1;

  if v_customer_name is null then raise exception 'The selected quote no longer exists'; end if;

  select * into v_state from public.rotation_state where kind = 'workload' for update;
  if not found then raise exception 'Additional Workload queue is not initialized'; end if;
  if v_state.current_profile_id is null then raise exception 'No agent has started the Additional Workload queue today. Click Available to start it'; end if;
  if v_state.current_profile_id is distinct from v_me.id then raise exception 'This Additional Workload turn belongs to another agent'; end if;

  insert into public.work_items(
    customer_name, dealer_id, work_type, original_owner_profile_id,
    assigned_profile_id, assignment_method, status, change_type, note,
    received_through, created_by, accepted_at, related_quote_source_work_item_id
  ) values (
    v_customer_name, v_dealer_id, p_work_type, coalesce(v_quote_owner_id, v_quote_assigned_id),
    v_me.id, 'workload_turn', 'active', nullif(btrim(p_change_type), ''), nullif(btrim(p_note), ''),
    'Linked quote', v_me.id, now(), p_related_quote_source_work_item_id
  ) returning * into v_item;

  insert into public.work_item_events(source_work_item_id, event_type, actor_profile_id, assigned_profile_id, details, created_at)
  values (
    p_related_quote_source_work_item_id,
    case when p_work_type = 'activation' then 'activation' else 'change' end,
    v_me.id,
    coalesce(v_quote_assigned_id, v_me.id),
    jsonb_build_object('service_work_item_id', v_item.id, 'change_type', nullif(btrim(p_change_type), ''), 'note', nullif(btrim(p_note), '')),
    now()
  );

  perform public.add_quote_note_if_present(p_related_quote_source_work_item_id, v_me.id, p_note);

  if p_work_type = 'activation' then
    perform public.finalize_quote_as_sold_from_activation(p_related_quote_source_work_item_id, v_me.id);
  end if;

  v_next := public.next_eligible_profile('workload', v_me.workload_position);

  update public.rotation_state
  set current_profile_id = coalesce(v_next, v_me.id),
      version = version + 1,
      updated_at = now(),
      updated_by = v_me.id
  where kind = 'workload';

  insert into public.turn_events(rotation, action, actor_profile_id, previous_profile_id, next_profile_id, work_item_id)
  values ('workload', 'claim', v_me.id, v_me.id, coalesce(v_next, v_me.id), v_item.id);

  return v_item;
end;
$function$

CREATE OR REPLACE FUNCTION public.claim_ringcentral_intake(p_intake_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET statement_timeout TO '30s'
AS $function$
declare
  v_intake          customer_intakes%rowtype;
  v_caller_id       uuid := auth.uid();
  v_caller_profile  profiles%rowtype;
  v_current_rc_id   uuid;
  v_quote_id        uuid;
begin
  begin
    select * into v_intake
    from customer_intakes
    where id = p_intake_id
    for update nowait;
  exception
    when lock_not_available then
      raise exception 'ALREADY_LOCKED: Another operation is in progress on this intake. Please try again.';
  end;

  if not found then
    raise exception 'INTAKE_NOT_FOUND: Intake % does not exist.', p_intake_id;
  end if;

  if v_intake.source_type != 'ringcentral' then
    raise exception 'NOT_RINGCENTRAL: This intake is not RingCentral-sourced.';
  end if;

  if v_intake.status not in ('submitted', 'waiting_for_claim') then
    raise exception 'INVALID_STATUS: Intake status "%" does not allow claiming.', v_intake.status;
  end if;

  if v_intake.assigned_to is not null then
    raise exception 'ALREADY_CLAIMED: This intake has already been claimed.';
  end if;

  select * into v_caller_profile
  from profiles
  where id = v_caller_id;

  if not found then
    raise exception 'CALLER_NOT_FOUND: No active profile for the authenticated user.';
  end if;

  -- Managers and super_admins can override the claim
  if v_caller_profile.role in ('manager', 'super_admin') then
    null;
  elsif v_caller_profile.role = 'agent' then
    if not v_caller_profile.ringcentral_active then
      raise exception 'NOT_RC_AGENT: You are not active in the RingCentral rotation.';
    end if;

    select current_profile_id into v_current_rc_id
    from rotation_state
    where kind = 'ringcentral';

    if v_current_rc_id is null then
      raise exception 'NO_RC_AGENT: No RingCentral agent is currently available.';
    end if;

    if v_caller_id != v_current_rc_id then
      raise exception 'NOT_YOUR_TURN: Current RingCentral turn belongs to another agent.';
    end if;
  else
    raise exception 'UNAUTHORIZED: Only Agents or Managers can claim intakes.';
  end if;

  -- Managers/super_admins are exempt from availability check
  if v_caller_profile.role not in ('manager', 'super_admin') and v_caller_profile.availability != 'available' then
    raise exception 'AGENT_UNAVAILABLE: You must set your status to Available before claiming.';
  end if;

  v_quote_id := _create_quote_from_intake(p_intake_id, v_caller_id, 'ringcentral_claim');

  update customer_intakes set
    status = 'claimed',
    assigned_to = v_caller_id,
    claimed_at = now(),
    assignment_method = 'ringcentral_claim',
    updated_at = now()
  where id = p_intake_id;

  insert into intake_history_events (
    intake_id, linked_quote_id, actor_id, actor_display_name, event_type, details
  ) values (
    p_intake_id, v_quote_id, v_caller_id, v_caller_profile.display_name,
    'claimed', 'RingCentral claim by ' || v_caller_profile.display_name
  );

  insert into notifications (
    recipient_id, notification_type, title, body, metadata, action_url
  ) values (
    v_intake.created_by, 'intake_claimed', 'Intake Claimed',
    v_intake.customer_name || ' claimed by ' || v_caller_profile.display_name,
    jsonb_build_object('intake_id', p_intake_id, 'quote_id', v_quote_id, 'agent_name', v_caller_profile.display_name, 'claimed_at', now()),
    '/tools/quotes/' || v_quote_id
  );

  insert into notifications (
    recipient_id, notification_type, title, body, metadata, action_url
  ) values (
    v_caller_id, 'quote_assigned', 'New Quote Assigned',
    v_intake.customer_name || ' — ' || replace(v_intake.source_type, '_', ' ') || ' / ' || replace(v_intake.line_of_business, '_', ' '),
    jsonb_build_object('quote_id', v_quote_id, 'intake_id', p_intake_id, 'customer_name', v_intake.customer_name, 'source_type', v_intake.source_type, 'line_of_business', v_intake.line_of_business),
    '/tools/quotes/' || v_quote_id
  );

  return v_quote_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.claim_ringcentral_quote(p_customer_name text, p_dealer_id uuid, p_work_type work_type, p_note text DEFAULT NULL::text)
 RETURNS work_items
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me public.profiles%rowtype;
  v_state public.rotation_state%rowtype;
  v_next uuid;
  v_item public.work_items%rowtype;
begin
  if not public.is_agent() then raise exception 'Agent permission required'; end if;
  if p_work_type not in ('new_quote', 'requote') then raise exception 'RingCentral rotation only accepts new quotes or requotes'; end if;
  perform public.ensure_daily_availability_reset();

  select * into v_me from public.profiles where id = auth.uid() and is_active for update;
  if not found then raise exception 'Active profile not found'; end if;
  if v_me.availability <> 'available' or not v_me.ringcentral_active then raise exception 'Set your status to Available before taking a RingCentral quote'; end if;

  select * into v_state from public.rotation_state where kind = 'ringcentral' for update;
  if not found then raise exception 'RingCentral queue is not initialized'; end if;
  if v_state.current_profile_id is null then raise exception 'No agent has started the RingCentral queue today. Click Available to start it'; end if;
  if v_state.current_profile_id is distinct from v_me.id then raise exception 'This RingCentral turn belongs to another agent'; end if;

  insert into public.work_items(customer_name, dealer_id, work_type, assigned_profile_id, assignment_method, status, note, received_through, created_by, accepted_at)
  values (trim(p_customer_name), p_dealer_id, p_work_type, v_me.id, 'ringcentral_turn', 'active', nullif(btrim(p_note), ''), 'RingCentral', v_me.id, now())
  returning * into v_item;

  perform public.add_quote_note_if_present(v_item.id, v_me.id, p_note);

  v_next := public.next_eligible_profile('ringcentral', v_me.ringcentral_position);

  update public.rotation_state
  set current_profile_id = coalesce(v_next, v_me.id),
      version = version + 1,
      updated_at = now(),
      updated_by = v_me.id
  where kind = 'ringcentral';

  insert into public.turn_events(rotation, action, actor_profile_id, previous_profile_id, next_profile_id, work_item_id)
  values ('ringcentral', 'claim', v_me.id, v_me.id, coalesce(v_next, v_me.id), v_item.id);

  return v_item;
end;
$function$

CREATE OR REPLACE FUNCTION public.claim_ringcentral_quote_v094(p_customer_name text, p_dealer_id uuid, p_salesperson_id uuid, p_work_type work_type, p_note text DEFAULT NULL::text)
 RETURNS work_items
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_item public.work_items%rowtype;
begin
  perform public.validate_dealer_salesperson(p_dealer_id, p_salesperson_id, true);
  select * into v_item
  from public.claim_ringcentral_quote(p_customer_name, p_dealer_id, p_work_type, p_note);

  update public.work_items
  set salesperson_id = p_salesperson_id
  where id = v_item.id
  returning * into v_item;
  return v_item;
end;
$function$

CREATE OR REPLACE FUNCTION public.claim_timed_quote(p_timer_id uuid)
 RETURNS work_items
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_timer public.quote_take_timers%rowtype;
  v_state public.rotation_state%rowtype;
  v_current public.profiles%rowtype;
  v_item public.work_items%rowtype;
  v_next uuid;
  v_position integer;
  v_elapsed integer;
begin
  if not public.is_agent() then raise exception 'Agent permission required'; end if;

  select * into v_timer
  from public.quote_take_timers
  where id = p_timer_id
  for update;
  if not found or v_timer.status <> 'active' then raise exception 'This rescue timer is no longer active'; end if;
  if v_timer.current_profile_id <> auth.uid() then raise exception 'This timed quote belongs to the current queue agent'; end if;

  select * into v_state
  from public.rotation_state
  where kind = v_timer.rotation
  for update;
  if v_state.current_profile_id is distinct from v_timer.current_profile_id then raise exception 'The queue moved and this timer is no longer valid'; end if;

  select * into v_current
  from public.profiles
  where id = v_timer.current_profile_id and role = 'agent' and is_active;
  if not found then raise exception 'Current agent profile is invalid'; end if;

  insert into public.work_items(
    customer_name, dealer_id, work_type, assigned_profile_id, assignment_method,
    status, note, received_through, created_by, assigned_at, accepted_at
  ) values (
    v_timer.customer_name, v_timer.dealer_id, v_timer.work_type, v_current.id,
    case when v_timer.rotation = 'whatsapp' then 'whatsapp_turn'::public.assignment_method else 'ringcentral_turn'::public.assignment_method end,
    'active', v_timer.note,
    case when v_timer.rotation = 'whatsapp' then 'WhatsApp dealership' else 'RingCentral' end,
    v_current.id, now(), now()
  ) returning * into v_item;

  v_elapsed := greatest(0, floor(extract(epoch from (now() - v_timer.received_at)))::integer);

  update public.quote_take_timers
  set status = 'claimed', claimed_by_profile_id = v_current.id,
      source_work_item_id = v_item.id, completed_at = now()
  where id = v_timer.id;

  perform public.add_quote_note_if_present(v_item.id, v_current.id, v_timer.note);

  insert into public.work_item_events(source_work_item_id, event_type, actor_profile_id, assigned_profile_id, details, created_at)
  values (
    v_item.id, 'timer_claimed', v_current.id, v_current.id,
    jsonb_build_object('timer_id', v_timer.id, 'received_at', v_timer.received_at, 'elapsed_seconds', v_elapsed),
    now()
  );

  v_position := case when v_timer.rotation = 'whatsapp' then v_current.whatsapp_position else v_current.ringcentral_position end;
  v_next := public.next_eligible_profile(v_timer.rotation, v_position);

  update public.rotation_state
  set current_profile_id = v_next, version = version + 1,
      updated_at = now(), updated_by = v_current.id
  where kind = v_timer.rotation;

  insert into public.turn_events(rotation, action, actor_profile_id, previous_profile_id, next_profile_id, work_item_id, reason)
  values (v_timer.rotation, 'claim', v_current.id, v_current.id, v_next, v_item.id, 'Current agent responded to rescue timer');

  return v_item;
end;
$function$

CREATE OR REPLACE FUNCTION public.claim_unlinked_workload_turn(p_customer_name text, p_dealer_id uuid, p_work_type work_type, p_original_owner_profile_id uuid DEFAULT NULL::uuid, p_change_type text DEFAULT NULL::text, p_note text DEFAULT NULL::text)
 RETURNS work_items
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me public.profiles%rowtype;
  v_state public.rotation_state%rowtype;
  v_next uuid;
  v_item public.work_items%rowtype;
  v_quote_source_id uuid;
  v_quote_agent_id uuid;
begin
  if not public.is_agent() then raise exception 'Agent permission required'; end if;
  if p_work_type not in ('activation', 'change') then raise exception 'Additional Workload only accepts activations or changes'; end if;
  if nullif(btrim(p_customer_name), '') is null then raise exception 'Customer name is required'; end if;

  perform public.ensure_daily_availability_reset();

  select * into v_me from public.profiles where id = auth.uid() and is_active for update;
  if not found then raise exception 'Active profile not found'; end if;
  if v_me.availability <> 'available' or not v_me.workload_active then raise exception 'Set your status to Available before taking Additional Workload'; end if;

  if p_original_owner_profile_id is not null and not exists (
    select 1 from public.profiles where id = p_original_owner_profile_id and role = 'agent' and is_active
  ) then
    raise exception 'Original owner is not an active agent';
  end if;

  select * into v_state from public.rotation_state where kind = 'workload' for update;
  if not found then raise exception 'Additional Workload queue is not initialized'; end if;
  if v_state.current_profile_id is null then raise exception 'No agent has started the Additional Workload queue today. Click Available to start it'; end if;
  if v_state.current_profile_id is distinct from v_me.id then raise exception 'This Additional Workload turn belongs to another agent'; end if;

  if p_work_type = 'activation' then
    v_quote_source_id := gen_random_uuid();
  end if;

  insert into public.work_items(
    customer_name, dealer_id, work_type, original_owner_profile_id,
    assigned_profile_id, assignment_method, status, change_type, note,
    received_through, created_by, accepted_at, related_quote_source_work_item_id
  ) values (
    trim(p_customer_name), p_dealer_id, p_work_type, p_original_owner_profile_id,
    v_me.id, 'workload_turn', 'active', nullif(btrim(p_change_type), ''), nullif(btrim(p_note), ''),
    'Legacy / Existing business', v_me.id, now(), v_quote_source_id
  ) returning * into v_item;

  if p_work_type = 'activation' then
    v_quote_agent_id := coalesce(p_original_owner_profile_id, v_me.id);

    insert into public.quote_outcomes(
      source_work_item_id, customer_name, dealer_id, work_type,
      original_owner_profile_id, assigned_profile_id, assignment_method,
      received_through, quote_created_at, assigned_at, accepted_at,
      decision, not_sold_reason, not_sold_reason_other, finalized_at
    ) values (
      v_quote_source_id, trim(p_customer_name), p_dealer_id, 'new_quote',
      p_original_owner_profile_id, v_quote_agent_id, 'workload_turn',
      'Legacy / Existing business', now(), now(), now(),
      'sold', null, null, now()
    );

    insert into public.work_item_events(source_work_item_id, event_type, actor_profile_id, assigned_profile_id, details, created_at)
    values (
      v_quote_source_id,
      'activation',
      v_me.id,
      v_quote_agent_id,
      jsonb_build_object('service_work_item_id', v_item.id, 'legacy_entry', true, 'note', nullif(btrim(p_note), '')),
      now()
    );

    perform public.add_quote_note_if_present(v_quote_source_id, v_me.id, p_note);
  end if;

  v_next := public.next_eligible_profile('workload', v_me.workload_position);

  update public.rotation_state
  set current_profile_id = coalesce(v_next, v_me.id),
      version = version + 1,
      updated_at = now(),
      updated_by = v_me.id
  where kind = 'workload';

  insert into public.turn_events(rotation, action, actor_profile_id, previous_profile_id, next_profile_id, work_item_id)
  values ('workload', 'claim', v_me.id, v_me.id, coalesce(v_next, v_me.id), v_item.id);

  return v_item;
end;
$function$

CREATE OR REPLACE FUNCTION public.claim_unlinked_workload_turn_v094(p_customer_name text, p_dealer_id uuid, p_salesperson_id uuid, p_work_type work_type, p_original_owner_profile_id uuid DEFAULT NULL::uuid, p_change_type text DEFAULT NULL::text, p_note text DEFAULT NULL::text)
 RETURNS work_items
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_item public.work_items%rowtype;
begin
  if p_dealer_id is not null then
    perform public.validate_dealer_salesperson(p_dealer_id, p_salesperson_id, true);
  elsif p_salesperson_id is not null then
    raise exception 'A salesperson cannot be selected without a source';
  end if;

  select * into v_item
  from public.claim_unlinked_workload_turn(
    p_customer_name,
    p_dealer_id,
    p_work_type,
    p_original_owner_profile_id,
    p_change_type,
    p_note
  );

  update public.work_items
  set salesperson_id = p_salesperson_id
  where id = v_item.id
  returning * into v_item;

  -- Legacy/unlinked Activations may create a Sold outcome inside the existing
  -- function before this wrapper receives the work item.
  update public.quote_outcomes
  set salesperson_id = p_salesperson_id
  where source_work_item_id = v_item.id
    and salesperson_id is null;

  return v_item;
end;
$function$

CREATE OR REPLACE FUNCTION public.claim_whatsapp_quote(p_customer_name text, p_dealer_id uuid, p_note text DEFAULT NULL::text)
 RETURNS work_items
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me public.profiles%rowtype;
  v_state public.rotation_state%rowtype;
  v_next uuid;
  v_item public.work_items%rowtype;
begin
  if not public.is_agent() then raise exception 'Agent permission required'; end if;
  perform public.ensure_daily_availability_reset();

  select * into v_me from public.profiles where id = auth.uid() and is_active for update;
  if not found then raise exception 'Active profile not found'; end if;
  if v_me.availability <> 'available' or not v_me.whatsapp_active then raise exception 'Set your status to Available before taking a WhatsApp quote'; end if;

  select * into v_state from public.rotation_state where kind = 'whatsapp' for update;
  if not found then raise exception 'WhatsApp queue is not initialized'; end if;
  if v_state.current_profile_id is null then raise exception 'No agent has started the WhatsApp queue today. Click Available to start it'; end if;
  if v_state.current_profile_id is distinct from v_me.id then raise exception 'This WhatsApp turn belongs to another agent'; end if;

  insert into public.work_items(customer_name, dealer_id, work_type, assigned_profile_id, assignment_method, status, note, received_through, created_by, accepted_at)
  values (trim(p_customer_name), p_dealer_id, 'new_quote', v_me.id, 'whatsapp_turn', 'active', nullif(btrim(p_note), ''), 'WhatsApp dealership', v_me.id, now())
  returning * into v_item;

  perform public.add_quote_note_if_present(v_item.id, v_me.id, p_note);

  v_next := public.next_eligible_profile('whatsapp', v_me.whatsapp_position);

  update public.rotation_state
  set current_profile_id = coalesce(v_next, v_me.id),
      version = version + 1,
      updated_at = now(),
      updated_by = v_me.id
  where kind = 'whatsapp';

  insert into public.turn_events(rotation, action, actor_profile_id, previous_profile_id, next_profile_id, work_item_id)
  values ('whatsapp', 'claim', v_me.id, v_me.id, coalesce(v_next, v_me.id), v_item.id);

  return v_item;
end;
$function$

CREATE OR REPLACE FUNCTION public.claim_whatsapp_quote_v094(p_customer_name text, p_dealer_id uuid, p_salesperson_id uuid, p_note text DEFAULT NULL::text)
 RETURNS work_items
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_item public.work_items%rowtype;
begin
  perform public.validate_dealer_salesperson(p_dealer_id, p_salesperson_id, true);
  select * into v_item
  from public.claim_whatsapp_quote(p_customer_name, p_dealer_id, p_note);

  update public.work_items
  set salesperson_id = p_salesperson_id
  where id = v_item.id
  returning * into v_item;
  return v_item;
end;
$function$

CREATE OR REPLACE FUNCTION public.claim_workload_turn(p_customer_name text, p_dealer_id uuid, p_work_type work_type, p_original_owner_profile_id uuid DEFAULT NULL::uuid, p_change_type text DEFAULT NULL::text)
 RETURNS work_items
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me public.profiles%rowtype;
  v_state public.rotation_state%rowtype;
  v_next uuid;
  v_item public.work_items%rowtype;
begin
  if not public.is_agent() then raise exception 'Agent permission required'; end if;
  if p_work_type not in ('activation', 'change') then raise exception 'Additional Workload only accepts activations or changes'; end if;

  select * into v_me from public.profiles where id = auth.uid() and is_active for update;
  if not found then raise exception 'Active profile not found'; end if;
  if v_me.availability <> 'available' or not v_me.workload_active then raise exception 'You are not eligible for the Additional Workload rotation'; end if;

  select * into v_state from public.rotation_state where kind = 'workload' for update;
  if v_state.current_profile_id is distinct from v_me.id then raise exception 'This Additional Workload turn belongs to another agent'; end if;

  insert into public.work_items(customer_name, dealer_id, work_type, original_owner_profile_id, assigned_profile_id, assignment_method, status, change_type, received_through, created_by, accepted_at)
  values (trim(p_customer_name), p_dealer_id, p_work_type, p_original_owner_profile_id, v_me.id, 'workload_turn', 'active', p_change_type, 'Manager routed', v_me.id, now())
  returning * into v_item;

  v_next := public.next_eligible_profile('workload', v_me.workload_position);
  if v_next is null then raise exception 'No eligible next agent'; end if;

  update public.rotation_state
  set current_profile_id = v_next, version = version + 1, updated_at = now(), updated_by = v_me.id
  where kind = 'workload';

  insert into public.turn_events(rotation, action, actor_profile_id, previous_profile_id, next_profile_id, work_item_id)
  values ('workload', 'claim', v_me.id, v_me.id, v_next, v_item.id);

  return v_item;
end;
$function$

CREATE OR REPLACE FUNCTION public.cs_intake_claim(p_submission_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_row public.cs_intake_submissions%rowtype;
  v_role text;
begin
  v_role := public.nhwd_role();

  -- Agents and sales_supervisors can claim intakes from the queue
  if v_role not in ('agent', 'manager', 'sales_supervisor') then
    raise exception 'Sales Agent or Manager access required to claim intakes.';
  end if;

  select * into v_row
  from public.cs_intake_submissions
  where id = p_submission_id
  for update;

  if not found then raise exception 'Intake not found.'; end if;
  if v_row.status::text <> 'submitted' then
    raise exception 'This intake is no longer available to claim.';
  end if;

  update public.cs_intake_submissions
  set status = 'claimed',
      claimed_by = auth.uid(),
      claimed_at = now(),
      updated_at = now()
  where id = p_submission_id
    and status::text = 'submitted';

  if not found then
    raise exception 'Another agent claimed this intake first.';
  end if;

  insert into public.cs_intake_events (submission_id, actor_id, event_type, detail)
  values (p_submission_id, auth.uid(), 'claimed', jsonb_build_object('role', v_role));
end;
$function$

CREATE OR REPLACE FUNCTION public.cs_intake_claim_ringcentral(p_submission_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me public.profiles%rowtype;
  v_state public.rotation_state%rowtype;
  v_row public.cs_intake_submissions%rowtype;
  v_next uuid;
  v_work_item_id uuid;
  v_was_already_claimed boolean := false;
begin
  if not public.is_agent() then
    raise exception 'Agent permission required.';
  end if;

  select *
  into v_me
  from public.profiles
  where id = auth.uid()
    and is_active
  for update;

  if not found then
    raise exception 'Active agent profile not found.';
  end if;

  select *
  into v_row
  from public.cs_intake_submissions
  where id = p_submission_id
  for update;

  if not found then
    raise exception 'Intake not found.';
  end if;

  if v_row.status::text = 'converted'
     and v_row.work_item_id is not null then
    if v_row.claimed_by = v_me.id then
      return v_row.work_item_id;
    end if;
    raise exception 'This intake was already converted by another agent.';
  end if;

  if v_row.intake_channel <> 'ringcentral' then
    raise exception 'This intake is manager/manual assigned and does not use the RingCentral turn.';
  end if;

  if v_row.status::text = 'claimed'
     and v_row.claimed_by = v_me.id
     and v_row.work_item_id is null then
    v_was_already_claimed := true;
  elsif v_row.status::text <> 'submitted' then
    raise exception 'This intake is no longer available to claim.';
  end if;

  if v_me.availability::text <> 'available'
     or not coalesce(v_me.ringcentral_active, false) then
    raise exception 'You are not eligible for the RingCentral rotation.';
  end if;

  select *
  into v_state
  from public.rotation_state
  where kind::text = 'ringcentral'
  for update;

  if not found then
    raise exception 'RingCentral rotation state is missing.';
  end if;

  if v_state.current_profile_id is distinct from v_me.id then
    raise exception 'This RingCentral turn belongs to another agent.';
  end if;

  if not v_was_already_claimed then
    update public.cs_intake_submissions
    set status = 'claimed',
        claimed_by = v_me.id,
        claimed_at = now(),
        updated_at = now()
    where id = p_submission_id
      and status::text = 'submitted';

    if not found then
      raise exception 'Another agent claimed this intake first.';
    end if;

    insert into public.cs_intake_events (
      submission_id,
      actor_id,
      event_type,
      detail
    )
    values (
      p_submission_id,
      v_me.id,
      'ringcentral_claimed',
      jsonb_build_object(
        'rotation_version', v_state.version,
        'intake_channel', 'ringcentral'
      )
    );
  else
    insert into public.cs_intake_events (
      submission_id,
      actor_id,
      event_type,
      detail
    )
    values (
      p_submission_id,
      v_me.id,
      'ringcentral_claim_recovered',
      jsonb_build_object(
        'rotation_version', v_state.version,
        'reason', 'Recovered from the previous claim-only workflow'
      )
    );
  end if;

  v_work_item_id := public.cs_intake_convert(p_submission_id);

  update public.work_items
  set assignment_method = 'ringcentral_turn',
      received_through = 'RingCentral / Customer Service intake',
      accepted_at = coalesce(accepted_at, now()),
      note = concat_ws(
        E'\n',
        nullif(note, ''),
        'Claimed from the Customer Service Intake Queue during the RingCentral turn.'
      ),
      updated_at = now()
  where id = v_work_item_id
    and assigned_profile_id = v_me.id;

  if not found then
    raise exception 'The intake converted, but its active Work Desk task could not be linked.';
  end if;

  insert into public.work_item_events (
    source_work_item_id,
    event_type,
    actor_profile_id,
    assigned_profile_id,
    details
  )
  values (
    v_work_item_id,
    'ringcentral_intake_claim_completed',
    v_me.id,
    v_me.id,
    jsonb_build_object(
      'intake_id', p_submission_id,
      'quote_kind', v_row.quote_kind,
      'line_of_business', v_row.line_of_business::text,
      'rotation_version_before', v_state.version,
      'recovered_existing_claim', v_was_already_claimed
    )
  );

  v_next := public.next_eligible_profile(
    'ringcentral'::public.rotation_kind,
    v_me.ringcentral_position
  );

  -- If no other eligible agent is found, wrap back to the same agent.
  if v_next is null then
    v_next := v_me.id;
  end if;

  update public.rotation_state
  set current_profile_id = v_next,
      version = version + 1,
      updated_at = now(),
      updated_by = v_me.id
  where kind::text = 'ringcentral';

  insert into public.turn_events (
    rotation,
    action,
    actor_profile_id,
    previous_profile_id,
    next_profile_id,
    work_item_id,
    reason
  )
  values (
    'ringcentral',
    'claim',
    v_me.id,
    v_me.id,
    v_next,
    v_work_item_id,
    case
      when v_was_already_claimed then 'Customer Service intake claim recovered and converted'
      else 'Customer Service intake claimed and converted'
    end
  );

  return v_work_item_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.cs_intake_convert(p_submission_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_row public.cs_intake_submissions%rowtype;
  v_work_item_id uuid;
  v_customer_name text;
  v_agent_name text;
  v_details jsonb;
begin
  select * into v_row
  from public.cs_intake_submissions
  where id = p_submission_id
  for update;

  if not found then raise exception 'Intake not found.'; end if;

  -- Idempotency: if already converted with a linked work_item, return it.
  if v_row.status::text = 'converted' and v_row.work_item_id is not null then
    return v_row.work_item_id;
  end if;

  if v_row.status::text <> 'claimed' or v_row.claimed_by is null then
    raise exception 'Claim or assign this intake first.';
  end if;

  -- Allow: managers, sales_supervisors, or the agent who claimed it
  if not public.can_manage_sales() and v_row.claimed_by <> auth.uid() then
    raise exception 'This intake belongs to another Sales Agent.';
  end if;

  v_customer_name := coalesce(nullif(trim(v_row.business_name), ''), trim(v_row.insured_first_name || ' ' || v_row.insured_last_name));

  -- Build details in a flat structure matching IntakeDataDisplay component props.
  v_details := jsonb_build_object(
    'intake_id', v_row.id,
    'csr_profile_id', v_row.created_by,
    'line_of_business', v_row.line_of_business::text,
    'quote_kind', v_row.quote_kind,
    'desired_coverage', v_row.desired_coverage,
    'business_name', v_row.business_name,
    'dot_number', v_row.dot_number,
    'business_type', v_row.business_type,
    'years_in_business', v_row.years_in_business,
    'operating_radius_miles', v_row.operating_radius_miles,
    'insured_first_name', v_row.insured_first_name,
    'insured_last_name', v_row.insured_last_name,
    'insured_dob', v_row.insured_dob,
    'insured_phone_primary', v_row.insured_phone_primary,
    'insured_email', v_row.insured_email,
    'addr_street', v_row.addr_street,
    'addr_city', v_row.addr_city,
    'addr_state', v_row.addr_state,
    'addr_zip', v_row.addr_zip,
    'current_carrier', v_row.current_carrier,
    'current_policy_number', v_row.current_policy_number,
    'current_premium', v_row.current_premium,
    'current_expiration', v_row.current_expiration,
    'csr_notes', v_row.csr_notes,
    'drivers', (select coalesce(jsonb_agg(
      jsonb_build_object(
        'first_name', d.first_name,
        'last_name', d.last_name,
        'dob', d.dob,
        'license_number', d.license_number,
        'license_state', d.license_state,
        'years_licensed', d.years_licensed,
        'sr22_required', d.sr22_required
      ) order by d.position
    ), '[]'::jsonb) from public.cs_intake_drivers d where d.submission_id = v_row.id),
    'vehicles', (select coalesce(jsonb_agg(
      jsonb_build_object(
        'year', v.year,
        'make', v.make,
        'model', v.model,
        'vin', v.vin,
        'usage', v.usage,
        'annual_mileage', v.annual_mileage
      ) order by v.position
    ), '[]'::jsonb) from public.cs_intake_vehicles v where v.submission_id = v_row.id)
  );

  if v_row.quote_kind = 'requote' then
    insert into public.work_items (
      customer_name, dealer_id, salesperson_id, work_type,
      original_owner_profile_id, assigned_profile_id, assignment_method,
      status, note, received_through, created_by, assigned_at
    ) values (
      v_customer_name, v_row.dealer_id, v_row.salesperson_id, 'requote',
      v_row.claimed_by, v_row.claimed_by, 'manual_quote',
      'active', 'Created from Customer Service structured intake', 'cs_intake', v_row.claimed_by, now()
    ) returning id into v_work_item_id;
  else
    insert into public.work_items (
      customer_name, dealer_id, salesperson_id, work_type,
      original_owner_profile_id, assigned_profile_id, assignment_method,
      status, note, received_through, created_by, assigned_at
    ) values (
      v_customer_name, v_row.dealer_id, v_row.salesperson_id, 'new_quote',
      v_row.claimed_by, v_row.claimed_by, 'manual_quote',
      'active', 'Created from Customer Service structured intake', 'cs_intake', v_row.claimed_by, now()
    ) returning id into v_work_item_id;
  end if;

  insert into public.work_item_events (
    source_work_item_id, event_type, actor_profile_id, assigned_profile_id, details
  ) values (
    v_work_item_id, 'created_from_cs_intake', auth.uid(), v_row.claimed_by, v_details
  );

  update public.cs_intake_submissions
  set status = 'converted', work_item_id = v_work_item_id, converted_at = now(), updated_at = now()
  where id = p_submission_id;

  insert into public.cs_intake_events (submission_id, actor_id, event_type, detail)
  values (p_submission_id, auth.uid(), 'converted', jsonb_build_object('work_item_id', v_work_item_id, 'sales_owner', v_row.claimed_by));

  if v_row.source_renewal_id is not null then
    update public.renewal_records
    set requote_work_item_id = v_work_item_id,
        requote_intake_id = p_submission_id,
        status = 'requote_sent',
        requote_sent_at = coalesce(requote_sent_at, now()),
        updated_at = now()
    where id = v_row.source_renewal_id;

    insert into public.renewal_events (record_id, actor_id, event_type, detail)
    values (v_row.source_renewal_id, auth.uid(), 'requote_quote_created', jsonb_build_object('intake_id', p_submission_id, 'work_item_id', v_work_item_id));
  end if;

  select display_name into v_agent_name from public.profiles where id = v_row.claimed_by;
  insert into public.user_notifications (recipient_profile_id, notification_type, title, message, entity_type, entity_id)
  values (v_row.created_by, 'assignment', 'Intake converted to a quote', coalesce(v_agent_name, 'Sales') || ' created the quote. Your intake credit was preserved.', 'work_item', v_work_item_id);

  return v_work_item_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.cs_intake_manager_assign(p_submission_id uuid, p_agent_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_creator uuid;
  v_name text;
begin
  -- Managers, super_admins, sales_supervisors, and CS supervisors can assign
  if not public.can_manage_sales() and not public.can_manage_customer_service() then
    raise exception 'Manager or Supervisor access required.';
  end if;

  -- Target must be an active user who handles sales quotes
  if not exists (
    select 1 from public.profiles
    where id = p_agent_id
      and is_active
      and role::text in ('agent', 'sales_supervisor')
  ) then
    raise exception 'Choose an active Sales Agent or Sales Supervisor.';
  end if;

  update public.cs_intake_submissions
  set status = 'claimed',
      claimed_by = p_agent_id,
      claimed_at = now(),
      intake_channel = 'manual',
      updated_at = now()
  where id = p_submission_id
    and status::text = 'submitted'
  returning created_by into v_creator;

  if not found then
    raise exception 'This intake is no longer available for assignment.';
  end if;

  select display_name into v_name from public.profiles where id = p_agent_id;

  insert into public.cs_intake_events (submission_id, actor_id, event_type, detail)
  values (
    p_submission_id,
    auth.uid(),
    'manager_assigned',
    jsonb_build_object(
      'assigned_to', p_agent_id,
      'assigned_name', v_name,
      'intake_channel', 'manual'
    )
  );

  insert into public.user_notifications (recipient_profile_id, notification_type, title, message, entity_type, entity_id)
  values (p_agent_id, 'assignment', 'Quote intake assigned to you', 'A Manager assigned a Customer Service intake. Review it and create the quote.', 'cs_intake', p_submission_id);

  insert into public.user_notifications (recipient_profile_id, notification_type, title, message, entity_type, entity_id)
  values (v_creator, 'assignment', 'Your intake was assigned', 'Sales Agent ' || coalesce(v_name, '') || ' received your quote intake.', 'cs_intake', p_submission_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.log_manual_quote(p_customer_name text, p_dealer_id uuid, p_work_type work_type, p_received_through text, p_note text DEFAULT NULL::text)
 RETURNS work_items
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me public.profiles%rowtype;
  v_item public.work_items%rowtype;
begin
  if not public.is_agent() then raise exception 'Agent permission required'; end if;
  if p_work_type not in ('new_quote', 'requote') then raise exception 'Manual quote must be a new quote or requote'; end if;
  if nullif(trim(p_received_through), '') is null then raise exception 'Input method is required'; end if;
  if nullif(trim(p_customer_name), '') is null then raise exception 'Customer name is required'; end if;

  select * into v_me from public.profiles where id = auth.uid() and is_active;
  if not found then raise exception 'Active profile not found'; end if;

