CREATE OR REPLACE FUNCTION public.start_quote_take_timer(p_rotation rotation_kind, p_received_at timestamp with time zone, p_customer_name text, p_dealer_id uuid, p_work_type work_type, p_note text DEFAULT NULL::text)
 RETURNS quote_take_timers
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me public.profiles%rowtype;
  v_current public.profiles%rowtype;
  v_state public.rotation_state%rowtype;
  v_timer public.quote_take_timers%rowtype;
  v_remaining integer;
begin
  if not public.is_agent() then raise exception 'Agent permission required'; end if;
  if p_rotation not in ('whatsapp', 'ringcentral') then raise exception 'Rescue timers are available only for quote queues'; end if;
  if p_received_at is null then raise exception 'Quote received time is required'; end if;
  if p_received_at > now() + interval '30 seconds' then raise exception 'Quote received time cannot be in the future'; end if;
  if now() - p_received_at > interval '24 hours' then raise exception 'The quote received time must be within the last 24 hours'; end if;
  if nullif(btrim(p_customer_name), '') is null then raise exception 'Customer name is required'; end if;
  if p_rotation = 'whatsapp' and p_work_type <> 'new_quote' then raise exception 'WhatsApp accepts new quotes only'; end if;
  if p_rotation = 'ringcentral' and p_work_type not in ('new_quote', 'requote') then raise exception 'RingCentral accepts new quotes or requotes'; end if;

  perform public.ensure_daily_availability_reset();

  select * into v_me
  from public.profiles
  where id = auth.uid() and role = 'agent' and is_active
  for update;
  if not found then raise exception 'Active agent profile not found'; end if;
  if v_me.availability <> 'available' then raise exception 'Set your status to Available before starting a rescue timer'; end if;
  if p_rotation = 'whatsapp' and not v_me.whatsapp_active then raise exception 'You are paused from the WhatsApp queue'; end if;
  if p_rotation = 'ringcentral' and not v_me.ringcentral_active then raise exception 'You are paused from the RingCentral queue'; end if;

  select * into v_state
  from public.rotation_state
  where kind = p_rotation
  for update;
  if not found or v_state.current_profile_id is null then raise exception 'This queue has no current agent'; end if;
  if v_state.current_profile_id = v_me.id then raise exception 'You already own this turn. Use the normal quote action'; end if;

  select * into v_current
  from public.profiles
  where id = v_state.current_profile_id and role = 'agent' and is_active;
  if not found then raise exception 'The current queue agent is invalid. Ask management to review Queue Health'; end if;

  if exists (
    select 1 from public.quote_take_timers
    where rotation = p_rotation and status = 'active'
  ) then
    raise exception 'A rescue timer is already active for this queue';
  end if;

  insert into public.quote_take_timers(
    rotation, current_profile_id, started_by_profile_id,
    received_at, deadline_at, customer_name, dealer_id, work_type, note
  ) values (
    p_rotation, v_current.id, v_me.id,
    p_received_at, p_received_at + interval '3 minutes',
    trim(p_customer_name), p_dealer_id, p_work_type, nullif(btrim(p_note), '')
  ) returning * into v_timer;

  v_remaining := greatest(0, ceil(extract(epoch from (v_timer.deadline_at - now())))::integer);

  insert into public.user_notifications(
    recipient_profile_id, notification_type, title, message, entity_type, entity_id
  ) values (
    v_current.id,
    'turn',
    'Rescue timer started',
    case
      when v_remaining <= 0 then format('%s started a rescue timer for %s. The 3-minute response period has already expired.', v_me.display_name, v_timer.customer_name)
      else format('%s started a rescue timer for %s. You have %s remaining to take your turn.', v_me.display_name, v_timer.customer_name, make_interval(secs => v_remaining)::text)
    end,
    'quote_take_timer',
    v_timer.id
  );

  insert into public.audit_log(actor_profile_id, action, entity_type, entity_id, new_value, reason)
  values (
    v_me.id,
    'start_quote_take_timer',
    'quote_take_timer',
    v_timer.id,
    jsonb_build_object(
      'rotation', p_rotation,
      'current_profile_id', v_current.id,
      'received_at', p_received_at,
      'deadline_at', v_timer.deadline_at,
      'customer_name', v_timer.customer_name
    ),
    nullif(btrim(p_note), '')
  );

  return v_timer;
end;
$function$

CREATE OR REPLACE FUNCTION public.start_quote_take_timer_v094(p_rotation rotation_kind, p_received_at timestamp with time zone, p_customer_name text, p_dealer_id uuid, p_salesperson_id uuid, p_work_type work_type, p_note text DEFAULT NULL::text)
 RETURNS quote_take_timers
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_timer public.quote_take_timers%rowtype;
begin
  if p_rotation::text <> 'whatsapp' then
    raise exception 'The rescue timer is available only for WhatsApp quotes.';
  end if;

  perform public.validate_dealer_salesperson(
    p_dealer_id,
    p_salesperson_id,
    true
  );

  select * into v_timer
  from public.start_quote_take_timer(
    p_rotation,
    p_received_at,
    p_customer_name,
    p_dealer_id,
    p_work_type,
    p_note
  );

  update public.quote_take_timers
  set salesperson_id = p_salesperson_id
  where id = v_timer.id
  returning * into v_timer;

  return v_timer;
end;
$function$

CREATE OR REPLACE FUNCTION public.steal_timed_quote(p_timer_id uuid)
 RETURNS work_items
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_timer public.quote_take_timers%rowtype;
  v_state public.rotation_state%rowtype;
  v_current public.profiles%rowtype;
  v_me public.profiles%rowtype;
  v_item public.work_items%rowtype;
  v_next uuid;
  v_position integer;
  v_elapsed integer;
begin
  if not public.is_agent() then raise exception 'Agent permission required'; end if;

  select * into v_timer
  from public.quote_take_timers
  where id = p_timer_id
  for update;
  if not found or v_timer.status <> 'active' then raise exception 'This rescue timer is no longer active'; end if;
  if v_timer.deadline_at > now() then raise exception 'The current agent still has time remaining'; end if;
  if v_timer.current_profile_id = auth.uid() then raise exception 'You own this turn. Use Take Timed Quote instead'; end if;

  select * into v_me
  from public.profiles
  where id = auth.uid() and role = 'agent' and is_active
  for update;
  if not found then raise exception 'Active agent profile not found'; end if;
  if v_me.availability <> 'available' then raise exception 'Set your status to Available before stealing a quote'; end if;
  if v_timer.rotation = 'whatsapp' and not v_me.whatsapp_active then raise exception 'You are paused from the WhatsApp queue'; end if;
  if v_timer.rotation = 'ringcentral' and not v_me.ringcentral_active then raise exception 'You are paused from the RingCentral queue'; end if;

  select * into v_state
  from public.rotation_state
  where kind = v_timer.rotation
  for update;
  if v_state.current_profile_id is distinct from v_timer.current_profile_id then raise exception 'The queue moved and this timer is no longer valid'; end if;

  select * into v_current
  from public.profiles
  where id = v_timer.current_profile_id and role = 'agent' and is_active;
  if not found then raise exception 'The missed agent profile is invalid'; end if;

  insert into public.work_items(
    customer_name, dealer_id, work_type, assigned_profile_id, assignment_method,
    status, note, received_through, created_by, assigned_at, accepted_at
  ) values (
    v_timer.customer_name, v_timer.dealer_id, v_timer.work_type, v_me.id,
    case when v_timer.rotation = 'whatsapp' then 'whatsapp_turn'::public.assignment_method else 'ringcentral_turn'::public.assignment_method end,
    'active', v_timer.note,
    case when v_timer.rotation = 'whatsapp' then 'WhatsApp dealership' else 'RingCentral' end,
    v_me.id, now(), now()
  ) returning * into v_item;

  v_elapsed := greatest(0, floor(extract(epoch from (now() - v_timer.received_at)))::integer);

  update public.quote_take_timers
  set status = 'stolen', claimed_by_profile_id = v_me.id,
      source_work_item_id = v_item.id, completed_at = now()
  where id = v_timer.id;

  insert into public.quote_take_events(
    source_work_item_id, rotation, received_at, taken_at,
    taker_profile_id, skipped_profile_ids, elapsed_seconds
  ) values (
    v_item.id, v_timer.rotation, v_timer.received_at, now(),
    v_me.id, array[v_current.id]::uuid[], v_elapsed
  );

  perform public.add_quote_note_if_present(v_item.id, v_me.id, v_timer.note);

  insert into public.work_item_events(source_work_item_id, event_type, actor_profile_id, assigned_profile_id, details, created_at)
  values (
    v_item.id, 'taken', v_me.id, v_me.id,
    jsonb_build_object(
      'timer_id', v_timer.id,
      'rotation', v_timer.rotation,
      'received_at', v_timer.received_at,
      'elapsed_seconds', v_elapsed,
      'missed_profile_id', v_current.id,
      'skipped_profile_ids', to_jsonb(array[v_current.id]::uuid[])
    ),
    now()
  );

  -- Preserve queue order: advance from the employee whose turn expired.
  v_position := case when v_timer.rotation = 'whatsapp' then v_current.whatsapp_position else v_current.ringcentral_position end;
  v_next := public.next_eligible_profile(v_timer.rotation, v_position);

  update public.rotation_state
  set current_profile_id = v_next, version = version + 1,
      updated_at = now(), updated_by = v_me.id
  where kind = v_timer.rotation;

  insert into public.turn_events(rotation, action, actor_profile_id, previous_profile_id, next_profile_id, work_item_id, reason)
  values (
    v_timer.rotation, 'claim', v_me.id, v_current.id, v_next, v_item.id,
    format('Quote stolen after %s seconds; missed current agent %s', v_elapsed, v_current.display_name)
  );

  insert into public.user_notifications(
    recipient_profile_id, notification_type, title, message, entity_type, entity_id
  ) values (
    v_current.id,
    'turn',
    'Quote was stolen',
    format('%s took %s after your 3-minute response period expired. Your turn was consumed and the regular queue order was preserved.', v_me.display_name, v_timer.customer_name),
    'work_item',
    v_item.id
  );

  return v_item;
end;
$function$

CREATE OR REPLACE FUNCTION public.take_quote_turn(p_rotation rotation_kind, p_received_at timestamp with time zone, p_customer_name text, p_dealer_id uuid, p_work_type work_type, p_note text DEFAULT NULL::text)
 RETURNS work_items
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me public.profiles%rowtype;
  v_state public.rotation_state%rowtype;
  v_current public.profiles%rowtype;
  v_queue_ids uuid[];
  v_taker_index integer;
  v_allowed_index integer;
  v_elapsed_seconds integer;
  v_skipped_ids uuid[] := '{}'::uuid[];
  v_next uuid;
  v_item public.work_items%rowtype;
  v_rotation_position integer;
  v_current_position integer;
begin
  if not public.is_agent() then raise exception 'Agent permission required'; end if;
  if p_rotation not in ('whatsapp', 'ringcentral') then raise exception 'Take is only available for quote rotations'; end if;
  if p_received_at is null then raise exception 'Quote received time is required'; end if;
  if p_received_at > now() + interval '30 seconds' then raise exception 'Quote received time cannot be in the future'; end if;
  if now() - p_received_at > interval '24 hours' then raise exception 'Take can only be used for quotes received within the last 24 hours'; end if;
  if nullif(btrim(p_customer_name), '') is null then raise exception 'Customer name is required'; end if;
  if p_rotation = 'whatsapp' and p_work_type <> 'new_quote' then raise exception 'WhatsApp Take only accepts new quotes'; end if;
  if p_rotation = 'ringcentral' and p_work_type not in ('new_quote', 'requote') then raise exception 'RingCentral Take accepts new quotes or requotes'; end if;

  perform public.ensure_daily_availability_reset();

  select * into v_me from public.profiles where id = auth.uid() and is_active for update;
  if not found then raise exception 'Active profile not found'; end if;
  if v_me.availability <> 'available' then raise exception 'Set your status to Available before using Take'; end if;
  if p_rotation = 'whatsapp' and not v_me.whatsapp_active then raise exception 'You are paused from the WhatsApp queue'; end if;
  if p_rotation = 'ringcentral' and not v_me.ringcentral_active then raise exception 'You are paused from the RingCentral queue'; end if;

  select * into v_state from public.rotation_state where kind = p_rotation for update;
  if not found then raise exception 'Queue is not initialized'; end if;
  if v_state.current_profile_id is null then raise exception 'No agent has started this queue today. Click Available first'; end if;

  select * into v_current from public.profiles where id = v_state.current_profile_id and is_active;
  if not found then raise exception 'Current queue agent is invalid. Refresh and try again'; end if;

  v_current_position := case when p_rotation = 'whatsapp' then v_current.whatsapp_position else v_current.ringcentral_position end;

  select array_agg(q.id order by q.sort_group, q.queue_position)
  into v_queue_ids
  from (
    select
      p.id,
      case when p_rotation = 'whatsapp' then p.whatsapp_position else p.ringcentral_position end as queue_position,
      case when (case when p_rotation = 'whatsapp' then p.whatsapp_position else p.ringcentral_position end) >= v_current_position then 0 else 1 end as sort_group
    from public.profiles p
    where p.role = 'agent'
      and p.is_active
      and p.availability = 'available'
      and case when p_rotation = 'whatsapp' then p.whatsapp_active else p.ringcentral_active end
  ) q;

  if coalesce(array_length(v_queue_ids, 1), 0) = 0 then raise exception 'No available eligible agents are in this queue'; end if;

  v_taker_index := array_position(v_queue_ids, v_me.id);
  if v_taker_index is null then raise exception 'You are not currently eligible to take this queue'; end if;
  if v_taker_index = 1 then raise exception 'You already own this turn. Use the normal queue action instead'; end if;

  v_elapsed_seconds := greatest(0, floor(extract(epoch from (now() - p_received_at)))::integer);
  v_allowed_index := least(array_length(v_queue_ids, 1), floor(v_elapsed_seconds / 180.0)::integer + 1);

  if v_taker_index > v_allowed_index then
    raise exception 'Not enough time has passed. Your 3-minute queue window has not opened yet';
  end if;

  if v_taker_index > 1 then
    v_skipped_ids := v_queue_ids[1:v_taker_index - 1];
  end if;

  insert into public.work_items(
    customer_name, dealer_id, work_type, assigned_profile_id, assignment_method,
    status, note, received_through, created_by, accepted_at
  ) values (
    trim(p_customer_name), p_dealer_id, p_work_type, v_me.id,
    case when p_rotation = 'whatsapp' then 'whatsapp_turn' else 'ringcentral_turn' end,
    'active', nullif(btrim(p_note), ''),
    case when p_rotation = 'whatsapp' then 'WhatsApp dealership' else 'RingCentral' end,
    v_me.id, now()
  ) returning * into v_item;

  insert into public.quote_take_events(
    source_work_item_id, rotation, received_at, taken_at,
    taker_profile_id, skipped_profile_ids, elapsed_seconds
  ) values (
    v_item.id, p_rotation, p_received_at, now(),
    v_me.id, coalesce(v_skipped_ids, '{}'::uuid[]), v_elapsed_seconds
  );

  perform public.add_quote_note_if_present(v_item.id, v_me.id, p_note);

  insert into public.work_item_events(source_work_item_id, event_type, actor_profile_id, assigned_profile_id, details, created_at)
  values (
    v_item.id,
    'taken',
    v_me.id,
    v_me.id,
    jsonb_build_object(
      'rotation', p_rotation,
      'received_at', p_received_at,
      'elapsed_seconds', v_elapsed_seconds,
      'skipped_profile_ids', to_jsonb(coalesce(v_skipped_ids, '{}'::uuid[]))
    ),
    now()
  );

  v_rotation_position := case when p_rotation = 'whatsapp' then v_me.whatsapp_position else v_me.ringcentral_position end;
  v_next := public.next_eligible_profile(p_rotation, v_rotation_position);

  update public.rotation_state
  set current_profile_id = coalesce(v_next, v_me.id),
      version = version + 1,
      updated_at = now(),
      updated_by = v_me.id
  where kind = p_rotation;

  insert into public.turn_events(rotation, action, actor_profile_id, previous_profile_id, next_profile_id, work_item_id, reason)
  values (
    p_rotation,
    'claim',
    v_me.id,
    v_state.current_profile_id,
    coalesce(v_next, v_me.id),
    v_item.id,
    format('Take action after %s seconds; skipped %s eligible agent(s)', v_elapsed_seconds, greatest(v_taker_index - 1, 0))
  );

  return v_item;
end;
$function$
